package scanner

import "strings"

// DefaultPorts returns the top 1,000 ports for the protocol, ranked by the
// Nmap nmap-services frequency data (TCP and UDP are ranked independently).
func DefaultPorts(protocol string) []string {
	var values string
	switch protocol {
	case "tcp":
		values = topTCPPorts
	case "udp":
		values = topUDPPorts
	default:
		return nil
	}
	return strings.Split(values, ",")
}

